import type { DungeonFloor, Room, TilePoint } from '@/core/dungeonTypes';
import { RoomKind, TileType } from '@/core/dungeonTypes';
import type { Rng } from '@/core/random';
import { createRng } from '@/core/random';
import type { TilesetMeta, TilesetTile } from '@/core/tilesetTypes';
import type { FloorDressingConfig } from '@/config/dressingConfig';
import { STAIRS_SIZE } from '@/config/gameConfig';
import { findRoomEntrances } from '@/dungeon/arenaGates';
import { isStairsTile } from '@/dungeon/stairs';
import { roomContainsTile } from '@/dungeon/rooms';
import { roomProximity } from '@/systems/BossHerald';

/** Brak kafla w warstwie. */
export const EMPTY_TILE = -1;

/** Warstwa do narysowania: indeks klatki arkusza dla każdego kafla mapy (y * width + x). */
export interface DressedLayer {
  readonly width: number;
  readonly height: number;
  /** Indeks klatki w arkuszu albo EMPTY_TILE. */
  readonly frames: Int32Array;
  /** 1 = kafel odbity w poziomie. */
  readonly flipX: Uint8Array;
}

/** h = krata w poprzek korytarza N-S (wejście od północy/południa), v = w poprzek korytarza E-W. */
export type GateOrientation = 'h' | 'v';
export type GateVisualState = 'open' | 'half' | 'closed';

export interface DressedGate {
  readonly x: number;
  readonly y: number;
  readonly orientation: GateOrientation;
  readonly frames: Readonly<Record<GateVisualState, number>>;
}

export interface DressedStairs {
  /** Lewy górny róg bloku schodów (= DungeonFloor.stairs). */
  readonly anchor: TilePoint;
  /** Klatki części bloku, wiersz po wierszu: zamknięte i otwarte. */
  readonly locked: readonly (readonly number[])[];
  readonly open: readonly (readonly number[])[];
}

/**
 * Wynik dekorowania piętra. Kolejność rysowania (od dołu): floorBase, floorDecal, floorFeature,
 * envShadow, walls, wallDecor, [postacie], overhead, overheadDecor. `walls` zawiera wszystkie ściany;
 * `overhead` to kopie ścian z podłogą od północy, rysowane drugi raz nad postaciami (postać stoi „za”
 * takim murem). `overheadDecor` (łuki, pajęczyny) leży tylko nad kaflami podłogi i nie ma kolizji —
 * kolizję buduje się wyłącznie z danych piętra.
 */
export interface DressedFloor {
  readonly floorBase: DressedLayer;
  readonly floorDecal: DressedLayer;
  readonly floorFeature: DressedLayer;
  readonly envShadow: DressedLayer;
  readonly walls: DressedLayer;
  /** Detale na licach murów (sztandary, kratki, wnęki). */
  readonly wallDecor: DressedLayer;
  readonly overhead: DressedLayer;
  readonly overheadDecor: DressedLayer;
  readonly stairs: DressedStairs;
  readonly gates: readonly DressedGate[];
}

// Bity masek — muszą zgadzać się z arkuszem (sprawdzane w dressFloor).
const N = 1;
const E = 2;
const S = 4;
const W = 8;
const NE = 1;
const SE = 2;
const SW = 4;
const NW = 8;

class LayerBuilder {
  readonly frames: Int32Array;
  readonly flipX: Uint8Array;
  /** Nazwy kafli — do zakazu powtórzeń z sąsiadem. */
  readonly names: (string | null)[];

  constructor(
    readonly width: number,
    readonly height: number,
  ) {
    this.frames = new Int32Array(width * height).fill(EMPTY_TILE);
    this.flipX = new Uint8Array(width * height);
    this.names = new Array<string | null>(width * height).fill(null);
  }

  set(x: number, y: number, frame: number, flip: boolean, name: string): void {
    const i = y * this.width + x;
    this.frames[i] = frame;
    this.flipX[i] = flip ? 1 : 0;
    this.names[i] = name;
  }

  nameAt(x: number, y: number): string | null {
    if (x < 0 || y < 0 || x >= this.width || y >= this.height) return null;
    return this.names[y * this.width + x] ?? null;
  }

  isEmpty(x: number, y: number): boolean {
    return this.frames[y * this.width + x] === EMPTY_TILE;
  }

  build(): DressedLayer {
    return { width: this.width, height: this.height, frames: this.frames, flipX: this.flipX };
  }
}

/** Dane spoza piętra, które dekorowanie musi uszanować. */
export interface DressingExtras {
  /** Kafle muru z uchwytem pochodni (LightPlanner) — bez detali lica w tym miejscu i obok. */
  readonly torches?: readonly TilePoint[];
}

/**
 * Dekoruje piętro kaflami z arkusza: warianty podłogi i ścian, nakładki, cienie, schody, kraty,
 * detale lica, łuki i pajęczyny.
 * Czysta funkcja: ten sam (piętro, arkusz, konfiguracja, seed, extras) daje ten sam wynik.
 * Losuje z własnego strumienia RNG (seed podaje wywołujący, z własną solą) — nie rusza zasad gry.
 */
export function dressFloor(
  floor: DungeonFloor,
  tileset: TilesetMeta,
  config: FloorDressingConfig,
  seed: number,
  extras: DressingExtras = {},
): DressedFloor {
  assertBits(tileset);
  const rng = createRng(seed);
  const { width, height } = floor;
  const ctx = new DressingContext(floor, tileset, config, rng);

  const floorBase = new LayerBuilder(width, height);
  const floorDecal = new LayerBuilder(width, height);
  const floorFeature = new LayerBuilder(width, height);
  const envShadow = new LayerBuilder(width, height);
  const walls = new LayerBuilder(width, height);
  const wallDecor = new LayerBuilder(width, height);
  const overhead = new LayerBuilder(width, height);
  const overheadDecor = new LayerBuilder(width, height);

  const gates = dressGates(ctx);
  const gateSet = new Set(gates.map((g) => g.y * width + g.x));
  const isPlain = (x: number, y: number) =>
    ctx.inBounds(x, y) && floor.tiles[y * width + x] === TileType.Floor && !gateSet.has(y * width + x);
  const inRoom = (x: number, y: number) => floor.rooms.some((room) => roomContainsTile(room, { x, y }));

  dressFloorBase(ctx, floorBase, isPlain, inRoom);
  dressTrail(ctx, floorDecal, isPlain);
  dressDecals(ctx, floorDecal, isPlain, clearZone(floor, gates, config.clearRadius));
  const stairs = dressStairs(ctx, floorFeature);
  dressEnvShadow(ctx, envShadow);
  dressWalls(ctx, walls, overhead);
  dressWallFaces(ctx, wallDecor, extras.torches ?? [], isPlain);
  dressOverheadDecor(ctx, overheadDecor, gateSet);

  return {
    floorBase: floorBase.build(),
    floorDecal: floorDecal.build(),
    floorFeature: floorFeature.build(),
    envShadow: envShadow.build(),
    walls: walls.build(),
    wallDecor: wallDecor.build(),
    overhead: overhead.build(),
    overheadDecor: overheadDecor.build(),
    stairs,
    gates,
  };
}

/** Orientacja kraty na wejściu do pokoju: wejście z góry/dołu = krata pozioma. */
export function gateOrientation(room: Room, tile: TilePoint): GateOrientation {
  return tile.y === room.y - 1 || tile.y === room.y + room.height ? 'h' : 'v';
}

class DressingContext {
  constructor(
    readonly floor: DungeonFloor,
    readonly tileset: TilesetMeta,
    readonly config: FloorDressingConfig,
    readonly rng: Rng,
  ) {}

  /**
   * Siła gniazda w kaflu (0..1): 1 w arenie bossa, liniowo malejąca do 0 na `nest.radiusTiles` od jej krawędzi.
   * 0 bez gniazda w konfiguracji albo bez areny.
   */
  nestStrength(x: number, y: number): number {
    const { nest } = this.config;
    const arena = this.floor.rooms[this.floor.bossRoomId];
    if (!nest || !arena) return 0;
    return roomProximity({ x, y }, arena, nest.radiusTiles);
  }

  inBounds(x: number, y: number): boolean {
    return x >= 0 && y >= 0 && x < this.floor.width && y < this.floor.height;
  }

  /** Ściana albo poza mapą. Kraty i schody to nie ściany. */
  isWall(x: number, y: number): boolean {
    return !this.inBounds(x, y) || this.floor.tiles[y * this.floor.width + x] === TileType.Wall;
  }

  tile(name: string): TilesetTile {
    const tile = this.tileset.tiles[name];
    if (!tile) throw new Error(`FloorDressing: brak kafla „${name}” w arkuszu.`);
    return tile;
  }

  group(name: string): readonly string[] {
    const group = this.tileset.groups[name];
    if (!group || group.length === 0) throw new Error(`FloorDressing: brak grupy „${name}” w arkuszu.`);
    return group;
  }

  /** Wariant z grupy wg wag, z pominięciem nazw sąsiadów (o ile zostaje jakaś inna opcja). */
  pickVariant(group: string, avoid: readonly (string | null)[]): string {
    const all = this.group(group);
    const allowed = all.filter((name) => !avoid.includes(name));
    return pickWeighted(this.rng, allowed.length > 0 ? allowed : all, (name) => this.tile(name).weight ?? 1);
  }

  rollFlip(tile: TilesetTile): boolean {
    return tile.flipX === true && this.rng.chance(this.config.flipChance);
  }
}

function pickWeighted<T>(rng: Rng, items: readonly T[], weightOf: (item: T) => number): T {
  const total = items.reduce((sum, item) => sum + weightOf(item), 0);
  let roll = rng.next() * total;
  for (const item of items) {
    roll -= weightOf(item);
    if (roll < 0) return item;
  }
  const last = items[items.length - 1];
  if (last === undefined) throw new Error('FloorDressing: pusta lista do losowania.');
  return last;
}

function framesOf(tile: TilesetTile): readonly (readonly number[])[] {
  return tile.frames ?? [[tile.frame]];
}

/** Kładzie element (także wielokaflowy) na warstwie; odbicie dotyczy całego elementu. */
function placeTile(layer: LayerBuilder, x: number, y: number, name: string, tile: TilesetTile, flip: boolean): void {
  const frames = framesOf(tile);
  for (let dy = 0; dy < tile.h; dy++) {
    for (let dx = 0; dx < tile.w; dx++) {
      const frame = frames[dy]?.[flip ? tile.w - 1 - dx : dx];
      if (frame === undefined) throw new Error(`FloorDressing: kafel „${name}” ma niepełne części.`);
      layer.set(x + dx, y + dy, frame, flip, name);
    }
  }
}

function assertBits(tileset: TilesetMeta): void {
  const { wall, envShadow } = tileset.autotile;
  const expected: ReadonlyArray<readonly [Readonly<Record<string, number>>, Record<string, number>]> = [
    [wall.bits, { N, E, S, W }],
    [wall.diagonal.bits, { NE, SE, SW, NW }],
    [envShadow.bits, { N, E, W }],
  ];
  for (const [actual, wanted] of expected) {
    for (const [key, bit] of Object.entries(wanted)) {
      if (actual[key] !== bit) throw new Error(`FloorDressing: arkusz ma inny bit ${key} (${actual[key]}), oczekiwano ${bit}.`);
    }
  }
}

// ---------------- podłoga ----------------

function dressFloorBase(
  ctx: DressingContext,
  layer: LayerBuilder,
  isPlain: (x: number, y: number) => boolean,
  inRoom: (x: number, y: number) => boolean,
): void {
  const { floor, config, rng } = ctx;
  // Najpierw wzory 2×2 w wolnych blokach zwykłej podłogi.
  for (let y = 0; y < floor.height - 1; y++) {
    for (let x = 0; x < floor.width - 1; x++) {
      const block = [
        [x, y],
        [x + 1, y],
        [x, y + 1],
        [x + 1, y + 1],
      ] as const;
      // Wzory 2×2 tylko w pokojach — korytarze mają bruk.
      if (!block.every(([bx, by]) => isPlain(bx, by) && inRoom(bx, by) && layer.isEmpty(bx, by))) continue;
      if (!rng.chance(config.macroChance)) continue;
      const name = ctx.pickVariant(config.floorMacroGroup, []);
      const tile = ctx.tile(name);
      placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
    }
  }
  // Pod każdą nie-ścianą (także schodami i kratami) leży baza: płyty w pokojach, bruk w korytarzach;
  // bez powtórzeń z lewym i górnym sąsiadem.
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (ctx.isWall(x, y) || !layer.isEmpty(x, y)) continue;
      const group = inRoom(x, y) ? config.floorGroup : config.corridorGroup;
      const name = ctx.pickVariant(group, [layer.nameAt(x - 1, y), layer.nameAt(x, y - 1)]);
      const tile = ctx.tile(name);
      placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
    }
  }
}

/** Kafle bez nakładek: wokół spawnu, schodów i krat (czytelność ważnych miejsc). */
function clearZone(floor: DungeonFloor, gates: readonly TilePoint[], radius: number): Uint8Array {
  const zone = new Uint8Array(floor.width * floor.height);
  const centers: TilePoint[] = [floor.playerSpawn, ...gates];
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (isStairsTile(floor, { x, y })) centers.push({ x, y });
    }
  }
  for (const c of centers) {
    for (let y = c.y - radius; y <= c.y + radius; y++) {
      for (let x = c.x - radius; x <= c.x + radius; x++) {
        if (x >= 0 && y >= 0 && x < floor.width && y < floor.height) zone[y * floor.width + x] = 1;
      }
    }
  }
  return zone;
}

function dressDecals(
  ctx: DressingContext,
  layer: LayerBuilder,
  isPlain: (x: number, y: number) => boolean,
  clear: Uint8Array,
): void {
  const { floor, config, rng } = ctx;
  const decorable = (x: number, y: number) => isPlain(x, y) && clear[y * floor.width + x] === 0 && layer.isEmpty(x, y);
  const groups = Object.keys(config.decalGroupWeights);
  const dustSides = [
    [config.dust.north, 0, -1],
    [config.dust.west, -1, 0],
    [config.dust.east, 1, 0],
  ] as const;

  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (!decorable(x, y)) continue;
      if (placeLargeDecal(ctx, layer, decorable, x, y)) continue;
      if (rng.chance(config.longCrackChance)) {
        const name = ctx.pickVariant(config.longCrackGroup, []);
        const tile = ctx.tile(name);
        let fits = true;
        for (let dy = 0; dy < tile.h; dy++) {
          for (let dx = 0; dx < tile.w; dx++) fits &&= decorable(x + dx, y + dy);
        }
        if (fits) {
          placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
          continue;
        }
      }
      if (rng.chance(config.decalChance)) {
        const group = pickWeighted(rng, groups, (g) => config.decalGroupWeights[g] ?? 0);
        const name = ctx.pickVariant(group, [layer.nameAt(x - 1, y), layer.nameAt(x, y - 1)]);
        const tile = ctx.tile(name);
        if (tile.w !== 1 || tile.h !== 1) throw new Error(`FloorDressing: zwykła nakładka „${name}” musi mieć 1×1.`);
        placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
        continue;
      }
      // Kurz nawiany pod ścianę — tylko od strony, gdzie faktycznie stoi mur.
      for (const [side, dx, dy] of dustSides) {
        if (ctx.isWall(x + dx, y + dy) && rng.chance(side.chance)) {
          const name = ctx.pickVariant(side.group, []);
          placeTile(layer, x, y, name, ctx.tile(name), false);
          break;
        }
      }
    }
  }
  dressNestDecals(ctx, layer, decorable);
}

/** Duża nakładka biomu (krok 32a), jeśli wylosowana i mieści się w całości na wolnej podłodze. */
function placeLargeDecal(
  ctx: DressingContext,
  layer: LayerBuilder,
  decorable: (x: number, y: number) => boolean,
  x: number,
  y: number,
): boolean {
  for (const { chance, group } of ctx.config.largeDecals ?? []) {
    if (!ctx.rng.chance(chance)) continue;
    const name = ctx.pickVariant(group, []);
    const tile = ctx.tile(name);
    let fits = true;
    for (let dy = 0; dy < tile.h; dy++) {
      for (let dx = 0; dx < tile.w; dx++) fits &&= decorable(x + dx, y + dy);
    }
    if (!fits) continue;
    placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
    return true;
  }
  return false;
}

// ---------------- schody i kraty ----------------

function dressStairs(ctx: DressingContext, layer: LayerBuilder): DressedStairs {
  const { floor, config } = ctx;
  const locked = ctx.tile(config.stairsTiles.locked);
  const open = ctx.tile(config.stairsTiles.open);
  for (const tile of [locked, open]) {
    if (tile.w !== STAIRS_SIZE || tile.h !== STAIRS_SIZE) {
      throw new Error(`FloorDressing: kafel schodów ma ${tile.w}×${tile.h}, a schody na mapie ${STAIRS_SIZE}×${STAIRS_SIZE}.`);
    }
  }
  placeTile(layer, floor.stairs.x, floor.stairs.y, config.stairsTiles.locked, locked, false);
  return { anchor: floor.stairs, locked: framesOf(locked), open: framesOf(open) };
}

/** Kraty: wejścia areny bossa i pokoju zasadzki (krok 49). */
function dressGates(ctx: DressingContext): DressedGate[] {
  const { floor, config } = ctx;
  const rooms = floor.rooms.filter((r) => r.id === floor.bossRoomId || r.kind === RoomKind.Ambush);
  return rooms.flatMap((room) =>
    findRoomEntrances(floor, room).map((point) => {
      const orientation = gateOrientation(room, point);
      const names = config.gateTiles[orientation];
      return {
        x: point.x,
        y: point.y,
        orientation,
        frames: { open: ctx.tile(names.open).frame, half: ctx.tile(names.half).frame, closed: ctx.tile(names.closed).frame },
      };
    }),
  );
}

// ---------------- cienie i ściany ----------------

function dressEnvShadow(ctx: DressingContext, layer: LayerBuilder): void {
  const { floor, tileset } = ctx;
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (ctx.isWall(x, y)) continue;
      const mask = (ctx.isWall(x, y - 1) ? N : 0) | (ctx.isWall(x + 1, y) ? E : 0) | (ctx.isWall(x - 1, y) ? W : 0);
      const name = tileset.autotile.envShadow.tiles[String(mask)];
      if (mask !== 0 && name) layer.set(x, y, ctx.tile(name).frame, false, name);
    }
  }
}

const FAR_AWAY = 0x3fffffff;

/** Odległość Czebyszewa każdego kafla od najbliższej nie-ściany (0 dla nie-ścian), BFS w 8 kierunkach. */
export function wallDistances(floor: DungeonFloor): Int32Array {
  const { width, height, tiles } = floor;
  const dist = new Int32Array(width * height).fill(-1);
  const queue: number[] = [];
  tiles.forEach((t, i) => {
    if (t !== TileType.Wall) {
      dist[i] = 0;
      queue.push(i);
    }
  });
  for (let head = 0; head < queue.length; head++) {
    const current = queue[head]!;
    const cx = current % width;
    const cy = Math.floor(current / width);
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        const nx = cx + dx;
        const ny = cy + dy;
        if (nx < 0 || ny < 0 || nx >= width || ny >= height) continue;
        const next = ny * width + nx;
        if (dist[next] !== -1) continue;
        dist[next] = dist[current]! + 1;
        queue.push(next);
      }
    }
  }
  // Mapa bez podłogi: wszystko traktujemy jako głęboką masę.
  return dist.map((d) => (d === -1 ? FAR_AWAY : d));
}

/** Warianty ścian losujemy bez zakazu powtórzeń: różnią się subtelnie, a zakaz zawyżałby udział zniszczeń. */
function dressWalls(ctx: DressingContext, walls: LayerBuilder, overhead: LayerBuilder): void {
  const { floor, tileset } = ctx;
  const { variants, diagonal, bands } = tileset.autotile.wall;
  const dist = wallDistances(floor);
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (!ctx.isWall(x, y)) continue;
      const d = dist[y * floor.width + x]!;
      if (d >= bands.fade) {
        const group = d >= bands.deep ? bands.groups.deep : bands.groups.fade;
        const name = ctx.pickVariant(group, []);
        walls.set(x, y, ctx.tile(name).frame, false, name);
        continue;
      }
      const mask =
        (ctx.isWall(x, y - 1) ? N : 0) | (ctx.isWall(x + 1, y) ? E : 0) | (ctx.isWall(x, y + 1) ? S : 0) | (ctx.isWall(x - 1, y) ? W : 0);
      let name: string;
      if (mask === diagonal.appliesToMask) {
        const diag =
          (ctx.isWall(x + 1, y - 1) ? 0 : NE) |
          (ctx.isWall(x + 1, y + 1) ? 0 : SE) |
          (ctx.isWall(x - 1, y + 1) ? 0 : SW) |
          (ctx.isWall(x - 1, y - 1) ? 0 : NW);
        const diagName = diagonal.tiles[String(diag)];
        name = diagName ?? ctx.pickVariant(variants[String(mask)] ?? '', []);
      } else {
        const group = variants[String(mask)];
        if (!group) throw new Error(`FloorDressing: arkusz nie opisuje maski ściany ${mask}.`);
        name = ctx.pickVariant(group, []);
      }
      const frame = ctx.tile(name).frame;
      walls.set(x, y, frame, false, name);
      // Mur z podłogą od północy zasłania postać stojącą za nim — druga kopia nad postaciami.
      if ((mask & N) === 0) overhead.set(x, y, frame, false, name);
    }
  }
}

// ---------------- detale lica i dekoracje nad postaciami (krok 19b) ----------------

/**
 * Detale na licu muru: tylko proste odcinki ściany z licem do pokoju (mur z północy, wschodu
 * i zachodu, pod spodem zwykła podłoga), nigdy na kaflu z pochodnią ani tuż obok niej.
 */
function dressWallFaces(
  ctx: DressingContext,
  layer: LayerBuilder,
  torches: readonly TilePoint[],
  isPlain: (x: number, y: number) => boolean,
): void {
  const { floor, config, rng } = ctx;
  const nearTorch = (x: number, y: number) => torches.some((t) => t.y === y && Math.abs(t.x - x) <= 1);
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      const straightFace = ctx.isWall(x, y) && ctx.isWall(x, y - 1) && ctx.isWall(x - 1, y) && ctx.isWall(x + 1, y);
      if (!straightFace || !isPlain(x, y + 1) || nearTorch(x, y)) continue;
      if (!rng.chance(config.wallFace.chance)) {
        // Gniazdo (krok 52): przy arenie bossa-pająka dodatkowe nici i jaja na licu.
        const nest = config.nest;
        const boost = nest ? ctx.nestStrength(x, y) : 0;
        if (nest && nest.wallFaceChance > 0 && boost > 0 && layer.isEmpty(x, y) && rng.chance(nest.wallFaceChance * boost)) {
          const name = ctx.pickVariant(nest.wallFaceGroup, [layer.nameAt(x - 1, y), layer.nameAt(x - 2, y)]);
          layer.set(x, y, ctx.tile(name).frame, false, name);
        }
        continue;
      }
      const name = ctx.pickVariant(config.wallFace.group, [layer.nameAt(x - 1, y), layer.nameAt(x - 2, y)]);
      layer.set(x, y, ctx.tile(name).frame, false, name);
    }
  }
}

/** Szansa pajęczyny w narożniku: zwykła, a w gnieździe (krok 52) rośnie ku arenie do `nest.cobwebChance`. */
function cobwebChance(ctx: DressingContext, x: number, y: number): number {
  const { cobweb, nest } = ctx.config;
  if (!nest) return cobweb.chance;
  return cobweb.chance + Math.max(0, nest.cobwebChance - cobweb.chance) * ctx.nestStrength(x, y);
}

/**
 * Łuki i pajęczyny — wyłącznie nad kaflami podłogi, w osobnej warstwie nad postaciami.
 * Łuk: przejście dokładnie tak szerokie jak kafel łuku (2) w górnej lub dolnej ścianie pokoju,
 * bez krat areny (nadproże zasłoniłoby pręty). Pajęczyna: górny narożnik pokoju z murem z dwóch stron.
 */
function dressOverheadDecor(ctx: DressingContext, layer: LayerBuilder, gateSet: ReadonlySet<number>): void {
  const { floor, config, rng } = ctx;
  const archName = ctx.pickVariant(config.archGroup, []);
  const arch = ctx.tile(archName);
  const isGate = (x: number, y: number) => gateSet.has(y * floor.width + x);
  for (const room of floor.rooms) {
    for (const y of [room.y - 1, room.y + room.height]) {
      let x = room.x;
      while (x < room.x + room.width) {
        if (ctx.isWall(x, y)) {
          x++;
          continue;
        }
        const start = x;
        while (x < room.x + room.width && !ctx.isWall(x, y)) x++;
        const cells = Array.from({ length: x - start }, (_, i) => start + i);
        const free = cells.every((cx) => !isGate(cx, y) && layer.isEmpty(cx, y));
        if (cells.length === arch.w && ctx.isWall(start - 1, y) && ctx.isWall(x, y) && free) {
          placeTile(layer, start, y, archName, arch, false);
        }
      }
    }
    const corners = [
      { x: room.x, y: room.y, side: -1, group: config.cobweb.nwGroup },
      { x: room.x + room.width - 1, y: room.y, side: 1, group: config.cobweb.neGroup },
    ];
    for (const c of corners) {
      const tucked = ctx.isWall(c.x, c.y - 1) && ctx.isWall(c.x + c.side, c.y);
      if (!tucked || ctx.isWall(c.x, c.y) || !layer.isEmpty(c.x, c.y) || !rng.chance(cobwebChance(ctx, c.x, c.y))) continue;
      const name = ctx.pickVariant(c.group, []);
      layer.set(c.x, c.y, ctx.tile(name).frame, false, name);
    }
  }
  dressCorridorCobwebs(ctx, layer, gateSet);
}

/** Dodatkowe nakładki ku arenie (krok 54): stosy kości, żar, plamy — gęstsze, im bliżej areny (poza samą areną). */
function dressNestDecals(ctx: DressingContext, layer: LayerBuilder, decorable: (x: number, y: number) => boolean): void {
  const { floor, config, rng } = ctx;
  const nest = config.nest;
  const arena = floor.rooms[floor.bossRoomId];
  if (!nest?.decals || !arena) return;
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (!decorable(x, y) || roomContainsTile(arena, { x, y })) continue;
      const strength = ctx.nestStrength(x, y);
      if (strength <= 0 || !rng.chance(nest.decals.chance * strength)) continue;
      const name = ctx.pickVariant(nest.decals.group, [layer.nameAt(x - 1, y), layer.nameAt(x, y - 1)]);
      const tile = ctx.tile(name);
      if (tile.w !== 1 || tile.h !== 1) throw new Error(`FloorDressing: nakładka gniazda „${name}” musi mieć 1×1.`);
      placeTile(layer, x, y, name, tile, ctx.rollFlip(tile));
    }
  }
}

/**
 * Ślady wleczenia i krwi (krok 54, pomysł właściciela): ostatnie kafle drogi od startu do wejścia areny. Smuga
 * biegnie wzdłuż kierunku marszu (poziomo/pionowo), gęstniejąc ku arenie; część to ciągi kropli.
 * Droga: najkrótsza po podłodze (BFS) ze spawnu do najbliższego wejścia; bez kafli areny, krat i okolic spawnu.
 */
function dressTrail(ctx: DressingContext, layer: LayerBuilder, isPlain: (x: number, y: number) => boolean): void {
  const { floor, config, rng } = ctx;
  const trail = config.nest?.trail;
  const arena = floor.rooms[floor.bossRoomId];
  if (!trail || !arena) return;
  const entrances = new Set(findRoomEntrances(floor, arena).map((p) => p.y * floor.width + p.x));
  const start = floor.playerSpawn.y * floor.width + floor.playerSpawn.x;
  const parent = new Map<number, number>([[start, -1]]);
  const queue = [start];
  let goal = -1;
  for (let head = 0; head < queue.length && goal < 0; head++) {
    const cur = queue[head]!;
    if (entrances.has(cur)) {
      goal = cur;
      break;
    }
    const cx = cur % floor.width;
    const cy = Math.floor(cur / floor.width);
    for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]] as const) {
      const nx = cx + dx;
      const ny = cy + dy;
      if (!ctx.inBounds(nx, ny)) continue;
      const next = ny * floor.width + nx;
      if (parent.has(next) || floor.tiles[next] !== TileType.Floor) continue;
      // Droga prowadzi przez wejścia do areny, ale nie przez jej wnętrze.
      if (roomContainsTile(arena, { x: nx, y: ny })) continue;
      parent.set(next, cur);
      queue.push(next);
    }
  }
  if (goal < 0) return;
  const path: number[] = [];
  for (let cur = goal; cur !== -1; cur = parent.get(cur)!) path.push(cur); // od wejścia ku startowi
  for (let i = 1; i < path.length && i <= trail.lengthTiles; i++) {
    const x = path[i]! % floor.width;
    const y = Math.floor(path[i]! / floor.width);
    const t = (i - 1) / Math.max(1, trail.lengthTiles - 1);
    if (!rng.chance(trail.chanceNear + (trail.chanceFar - trail.chanceNear) * t)) continue;
    if (!isPlain(x, y) || !layer.isEmpty(x, y) || roomContainsTile(arena, { x, y })) continue;
    if (Math.max(Math.abs(x - floor.playerSpawn.x), Math.abs(y - floor.playerSpawn.y)) <= 2) continue;
    // Kierunek marszu ku arenie: z kafla do poprzedniego na ścieżce (bliżej wejścia).
    const toward = path[i - 1]!;
    const dx = Math.abs((toward % floor.width) - x);
    const dy = Math.abs(Math.floor(toward / floor.width) - y);
    const group = rng.chance(trail.dropChance) ? 'decal.trailDrop' : dx >= dy ? 'decal.trailH' : 'decal.trailV';
    const name = ctx.pickVariant(group, [layer.nameAt(x - 1, y), layer.nameAt(x, y - 1)]);
    placeTile(layer, x, y, name, ctx.tile(name), ctx.rollFlip(ctx.tile(name)));
  }
}

/**
 * Pajęczyny w korytarzach przed areną (krok 53): pod górnym murem albo przy bocznym murze korytarza, im bliżej areny,
 * tym gęściej. Wariant (NW/NE) wg muru z boku; bez dwóch sąsiadujących, żeby korytarz nie zamienił się w kokon.
 */
function dressCorridorCobwebs(ctx: DressingContext, layer: LayerBuilder, gateSet: ReadonlySet<number>): void {
  const { floor, config, rng } = ctx;
  const nest = config.nest;
  if (!nest || nest.corridorCobwebChance <= 0) return;
  for (let y = 0; y < floor.height; y++) {
    for (let x = 0; x < floor.width; x++) {
      if (floor.tiles[y * floor.width + x] !== TileType.Floor || gateSet.has(y * floor.width + x)) continue;
      if (floor.rooms.some((room) => roomContainsTile(room, { x, y }))) continue;
      const wallEast = ctx.isWall(x + 1, y);
      const wallWest = ctx.isWall(x - 1, y);
      if ((!ctx.isWall(x, y - 1) && !wallEast && !wallWest) || !layer.isEmpty(x, y) || !layer.isEmpty(x - 1, y) || !layer.isEmpty(x, y - 1)) continue;
      const strength = ctx.nestStrength(x, y);
      if (strength <= 0 || !rng.chance(nest.corridorCobwebChance * strength)) continue;
      const side = wallEast ? 1 : wallWest ? -1 : rng.chance(0.5) ? 1 : -1;
      const name = ctx.pickVariant(side === 1 ? config.cobweb.neGroup : config.cobweb.nwGroup, []);
      layer.set(x, y, ctx.tile(name).frame, false, name);
    }
  }
}
